// src/checker.ts
function createChecker({ fixtures, env }) {
  const userAgent = env.SEC_USER_AGENT;
  if (!fixtures && !userAgent) {
    throw new Error(
      "SEC_USER_AGENT is not set. Locally, add it to .env (see .env.example). On Vercel, add it under Settings > Environment Variables and redeploy. Or use demo mode (npm run dev:demo, or HYPECHECK_DEMO=1 on Vercel)."
    );
  }
  const sec = new SecClient({
    userAgent: userAgent ?? "HypeCheck demo",
    fetch: fixtures ? createFixtureFetch() : void 0
  });
  const extractor = env.ANTHROPIC_API_KEY ? createAnthropicExtractor({ apiKey: env.ANTHROPIC_API_KEY, model: env.HYPECHECK_MODEL }) : createRuleBasedExtractor();
  const deps = {
    extractor,
    // Register new data sources here.
    sources: [createSecRevenueSource({ sec }), createSecFigureSource({ sec })],
    cache: new MemoryCache()
  };
  return {
    check: (text) => checkPost(text, deps),
    describe: () => `extractor: ${extractor.name}, data: ${fixtures ? "demo fixtures" : "live SEC"}`
  };
}

// src/vercel.ts
var MAX_BODY_BYTES = 64 * 1024;
var checker = null;
function send(res, status, body) {
  res.statusCode = status;
  res.setHeader("content-type", "application/json");
  res.setHeader("cache-control", "no-store");
  res.end(JSON.stringify(body));
}
async function readText(req) {
  if (req.body && typeof req.body === "object") {
    const text = req.body.text;
    return typeof text === "string" ? text : null;
  }
  let raw = typeof req.body === "string" ? req.body : "";
  if (!raw) {
    const chunks = [];
    let size = 0;
    for await (const chunk of req) {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) throw new InputError("That post is too long.");
      chunks.push(chunk);
    }
    raw = Buffer.concat(chunks).toString("utf8");
  }
  try {
    const text = JSON.parse(raw)?.text;
    return typeof text === "string" ? text : null;
  } catch {
    return null;
  }
}
async function handler(req, res) {
  const demo = process.env.HYPECHECK_DEMO === "1";
  try {
    checker ??= createChecker({ fixtures: demo, env: process.env });
  } catch (error) {
    return send(res, 500, { error: error instanceof Error ? error.message : "Server is not configured." });
  }
  if (req.method === "GET") return send(res, 200, { ok: true, mode: demo ? "demo" : "live" });
  if (req.method !== "POST") return send(res, 405, { error: "Use POST." });
  try {
    const text = await readText(req);
    if (text === null) throw new InputError('Send JSON like {"text": "..."}');
    send(res, 200, await checker.check(text));
  } catch (error) {
    if (error instanceof InputError) return send(res, 400, { error: error.message });
    console.error(error);
    send(res, 500, { error: "The check couldn't be completed. Try again in a minute." });
  }
}
export {
  handler as default
};
